<template>
  <div class="notice123">
    <div class="notice-wrap">
      <div class="notice">
        <p class="notice-cont" v-if="tit">{{tit}}
        </p>
        <p class="notice-cont" v-else>系统维护中，请耐心等待!
        </p>
      </div>
    </div>

  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'

// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const codes = ref('')
const tit = ref('')
// 生命周期
onMounted(() => {
    getbacks()
})
const getbacks = async()  =>{
  try {
     const res = await userStore.getSystemstop();
    if(res.data!=1){
      tit.value = res.data;
    }else{
      localStorage.clear();
      router.push({path: '/login'});
    }
  } catch (error) {
    console.log('操作失败，请重试')
  }
}
</script>
<style scoped>
  .notice123{
    width: 100%;
    height: 100vh;
    background:#fff;
  }
  .notice-wrap {
    padding-top: 100px;
  }

  .notice {
    margin: 0 auto;
    width: 420px;
    height: 618px;
    background: url(../../assets/images/weih.png) no-repeat;
    background-size:100%;
    position: relative;
  }
  .notice p {
    font-size: 20px;
    color: #55555;
    font-weight: bold;
    position: absolute;
    top: 240px;
    left:100px;
  }
</style>